package com.example.orderprocessing.controller;
import com.example.orderprocessing.dto.ProductRequest; import com.example.orderprocessing.service.ProductService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/products") public class ProductController {private final ProductService service; public ProductController(ProductService service){this.service=service;} @GetMapping public Object all(){return service.all();} @GetMapping("/{id}") public Object get(@PathVariable Long id){return service.get(id);} @PostMapping public Object create(@Valid @RequestBody ProductRequest request){return service.create(request);} @PutMapping("/{id}") public Object update(@PathVariable Long id,@Valid @RequestBody ProductRequest request){return service.update(id,request);} @PostMapping("/{id}/stock") public Object addStock(@PathVariable Long id,@RequestParam int quantity){return service.addStock(id,quantity);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){service.delete(id);} }
